988	        if (resource != null) {
989	            getRouteCollection().setResource(resource);
990	        }
991	        // must stop and remove existing running routes
992	        for (RouteDefinition route : getRouteCollection().getRoutes()) {
993	            camelContext.getRouteController().stopRoute(route.getRouteId());
994	            camelContext.removeRoute(route.getRouteId());
995	        }
