38	import org.apache.camel.Route;
39	import org.apache.camel.RouteAware;
40	import org.apache.camel.Service;
41	import org.apache.camel.StartupStep;
42	import org.apache.camel.spi.IdAware;
43	import org.apache.camel.spi.InternalProcessor;
44	import org.apache.camel.spi.LifecycleStrategy;
45	import org.apache.camel.spi.RouteIdAware;
46	import org.apache.camel.spi.RoutePolicy;
47	import org.apache.camel.spi.StartupStepRecorder;
48	import org.apache.camel.support.ChildServiceSupport;
49	import org.apache.camel.support.EventHelper;
50	import org.apache.camel.support.PatternHelper;
51	import org.apache.camel.support.service.ServiceHelper;
52	import org.slf4j.MDC;
53	
54	import static org.apache.camel.spi.UnitOfWork.MDC_CAMEL_CONTEXT_ID;
55	import static org.apache.camel.spi.UnitOfWork.MDC_ROUTE_ID;
56	
57	/**
58	 * Represents the runtime objects for a given route so that it can be stopped independently of other routes
59	 */
60	public class RouteService extends ChildServiceSupport {
61	
62	    private final CamelContext camelContext;
63	    private final StartupStepRecorder startupStepRecorder;
64	    private final Route route;
65	    private boolean removingRoutes;
66	    private Consumer input;
67	    private final Lock lock = new ReentrantLock();
68	    private final AtomicBoolean setUpDone = new AtomicBoolean();
69	    private final AtomicBoolean warmUpDone = new AtomicBoolean();
70	    private final AtomicBoolean endpointDone = new AtomicBoolean();
71	
72	    public RouteService(Route route) {
73	        this.route = route;
74	        this.camelContext = this.route.getCamelContext();
75	        this.startupStepRecorder = this.camelContext.getCamelContextExtension().getStartupStepRecorder();
76	    }
77	
78	    public String getId() {
79	        return route.getId();
80	    }
81	
82	    public String getLocation() {
83	        return route.getSourceLocationShort();
84	    }
85	
86	    public CamelContext getCamelContext() {
87	        return camelContext;
88	    }
89	
90	    public Route getRoute() {
91	        return route;
92	    }
93	
94	    /**
95	     * Gather all the endpoints this route service uses
96	     * <p/>
97	     * This implementation finds the endpoints by searching all the child services for {@link EndpointAware} processors
98	     * which uses an endpoint.
99	     */
100	    public Set<Endpoint> gatherEndpoints() {
101	        Set<Endpoint> answer = new LinkedHashSet<>();
102	        Set<Service> services = gatherChildServices();
103	        for (Service service : services) {
104	            if (service instanceof EndpointAware endpointAware) {
105	                Endpoint endpoint = endpointAware.getEndpoint();
106	                if (endpoint != null) {
107	                    answer.add(endpoint);
108	                }
109	            }
110	        }
111	        return answer;
112	    }
113	
114	    public Consumer getInput() {
115	        return input;
116	    }
117	
118	    public boolean isRemovingRoutes() {
119	        return removingRoutes;
120	    }
121	
122	    public void setRemovingRoutes(boolean removingRoutes) {
123	        this.removingRoutes = removingRoutes;
124	    }
125	
126	    public void warmUp() throws FailedToStartRouteException {
127	        try {
128	            doWarmUp();
129	        } catch (Exception e) {
130	            throw new FailedToStartRouteException(getId(), getLocation(), e.getLocalizedMessage(), e);
131	        }
132	    }
133	
134	    public void setUp() throws FailedToStartRouteException {
135	        if (setUpDone.compareAndSet(false, true)) {
136	            try {
137	                doSetup();
138	            } catch (Exception e) {
139	                throw new FailedToStartRouteException(getId(), getLocation(), e.getLocalizedMessage(), e);
140	            }
141	        }
142	    }
143	
144	    public boolean isAutoStartup() {
145	        if (!getCamelContext().isAutoStartup()) {
146	            return false;
147	        }
148	        if (!getRoute().isAutoStartup()) {
149	            return false;
150	        }
151	        if (getCamelContext().getAutoStartupExcludePattern() != null) {
152	            String[] patterns = getCamelContext().getAutoStartupExcludePattern().split(",");
153	            String id = getRoute().getRouteId();
154	            String url = getRoute().getEndpoint().getEndpointUri();
155	            if (PatternHelper.matchPatterns(id, patterns) || PatternHelper.matchPatterns(url, patterns)) {
156	                return false;
157	            }
158	        }
159	        return true;
160	    }
161	
162	    protected void doSetup() throws Exception {
163	        lock.lock();
164	        try {
165	            // to setup we initialize the services
166	            ServiceHelper.initService(route.getEndpoint());
167	
168	            try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
169	
170	                // ensure services are initialized first
171	                route.initializeServices();
172	                List<Service> services = route.getServices();
173	
174	                // split into consumers and child services as we need to start the consumers
175	                // afterwards to avoid them being active while the others start
176	                List<Service> list = new ArrayList<>();
177	                for (Service service : services) {
178	
179	                    // inject the route
180	                    if (service instanceof RouteAware routeAware) {
181	                        routeAware.setRoute(route);
182	                    }
183	                    if (service instanceof RouteIdAware routeIdAware) {
184	                        routeIdAware.setRouteId(route.getId());
185	                    }
186	                    // inject camel context
187	                    CamelContextAware.trySetCamelContext(service, camelContext);
188	
189	                    if (service instanceof Consumer consumer) {
190	                        this.input = consumer;
191	                    } else {
192	                        list.add(service);
193	                    }
194	                }
195	                initChildServices(list);
196	            }
197	        } finally {
198	            lock.unlock();
199	        }
200	    }
201	
202	    protected void doWarmUp() throws Exception {
203	        lock.lock();
204	        try {
205	            if (endpointDone.compareAndSet(false, true)) {
206	                // endpoints should only be started once as they can be reused on other routes
207	                // and whatnot, thus their lifecycle is to start once, and only to stop when Camel shutdown
208	                // ensure endpoint is started first (before the route services, such as the consumer)
209	                ServiceHelper.startService(route.getEndpoint());
210	            }
211	
212	            if (warmUpDone.compareAndSet(false, true)) {
213	
214	                try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
215	                    // warm up the route first
216	                    route.warmUp();
217	
218	                    startChildServices(route, childServices);
219	
220	                    // fire event
221	                    EventHelper.notifyRouteAdded(camelContext, route);
222	                }
223	
224	                // ensure lifecycle strategy is invoked which among others enlist the route in JMX
225	                for (LifecycleStrategy strategy : camelContext.getLifecycleStrategies()) {
226	                    strategy.onRoutesAdd(Collections.singletonList(route));
227	                }
228	
229	                // add routes to camel context
230	                camelContext.getCamelContextExtension().addRoute(route);
231	
232	                // add the routes to the inflight registry so they are pre-installed
233	                camelContext.getInflightRepository().addRoute(route.getId());
234	            }
235	        } finally {
236	            lock.unlock();
237	        }
238	    }
239	
240	    @Override
241	    protected void doStart() {
242	        try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
243	            // fire event
244	            EventHelper.notifyRouteStarting(camelContext, route);
245	        }
246	
247	        // ensure we are warmed up
248	        warmUp();
249	
250	        try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
251	            // start the route itself
252	            ServiceHelper.startService(route);
253	
254	            // invoke callbacks on route policy
255	            routePolicyCallback(RoutePolicy::onStart);
256	
257	            // fire event
258	            EventHelper.notifyRouteStarted(camelContext, route);
259	        }
260	    }
261	
262	    @Override
263	    protected void doStop() {
264	        try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
265	            // fire event
266	            EventHelper.notifyRouteStopping(camelContext, route);
267	        }
268	
269	        // if we are stopping CamelContext then we are shutting down
270	        boolean isShutdownCamelContext = camelContext.isStopping();
271	
272	        if (isShutdownCamelContext || isRemovingRoutes()) {
273	            // need to call onRoutesRemove when the CamelContext is shutting down or Route is shutdown
274	            for (LifecycleStrategy strategy : camelContext.getLifecycleStrategies()) {
275	                strategy.onRoutesRemove(Collections.singletonList(route));
276	            }
277	        }
278	
279	        try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
280	            // gather list of services to stop
281	            Set<Service> services = gatherChildServices();
282	
283	            // stop services
284	            stopChildServices(route, services, isShutdownCamelContext);
285	
286	            // stop the route itself
287	            if (isShutdownCamelContext) {
288	                ServiceHelper.stopAndShutdownServices(route);
289	            } else {
290	                ServiceHelper.stopService(route);
291	            }
292	
293	            // invoke callbacks on route policy
294	            routePolicyCallback(RoutePolicy::onStop);
295	
296	            // fire event
297	            EventHelper.notifyRouteStopped(camelContext, route);
298	        }
299	        if (isRemovingRoutes()) {
300	            camelContext.getCamelContextExtension().removeRoute(route);
301	        }
302	        // need to redo if we start again after being stopped
303	        input = null;
304	        childServices = null;
305	        warmUpDone.set(false);
306	        setUpDone.set(false);
307	        endpointDone.set(false);
308	        setUpDone.set(false);
309	        warmUpDone.set(false);
310	    }
311	
312	    @Override
313	    protected void doShutdown() {
314	        try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
315	            // gather list of services to shutdown
316	            Set<Service> services = gatherChildServices();
317	
318	            // shutdown services
319	            stopChildServices(route, services, true);
320	
321	            // shutdown the route itself
322	            ServiceHelper.stopAndShutdownServices(route);
323	
324	            // endpoints should only be stopped when Camel is shutting down
325	            // see more details in the warmUp method
326	            ServiceHelper.stopAndShutdownServices(route.getEndpoint());
327	
328	            // invoke callbacks on route policy
329	            routePolicyCallback(RoutePolicy::onRemove);
330	
331	            // fire event
332	            EventHelper.notifyRouteRemoved(camelContext, route);
333	        }
334	
335	        // need to call onRoutesRemove when the CamelContext is shutting down or Route is shutdown
336	        for (LifecycleStrategy strategy : camelContext.getLifecycleStrategies()) {
337	            strategy.onRoutesRemove(Collections.singletonList(route));
338	        }
339	
340	        // remove the routes from the inflight registry
341	        camelContext.getInflightRepository().removeRoute(route.getId());
342	
343	        // remove the routes from the collections
344	        camelContext.getCamelContextExtension().removeRoute(route);
345	
346	        // clear inputs on shutdown
347	        input = null;
348	        childServices = null;
349	        warmUpDone.set(false);
350	        setUpDone.set(false);
351	        endpointDone.set(false);
352	    }
353	
354	    @Override
355	    protected void doSuspend() {
356	        // suspend and resume logic is provided by DefaultCamelContext which leverages ShutdownStrategy
357	        // to safely suspend and resume
358	        try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
359	            routePolicyCallback(RoutePolicy::onSuspend);
360	        }
361	    }
362	
363	    @Override
364	    protected void doResume() {
365	        // suspend and resume logic is provided by DefaultCamelContext which leverages ShutdownStrategy
366	        // to safely suspend and resume
367	        try (MDCHelper mdcHelper = new MDCHelper(route.getId())) {
368	            routePolicyCallback(RoutePolicy::onResume);
369	        }
370	    }
371	
372	    private void routePolicyCallback(BiConsumer<RoutePolicy, Route> callback) {
373	        if (route.getRoutePolicyList() != null) {
374	            for (RoutePolicy routePolicy : route.getRoutePolicyList()) {
375	                callback.accept(routePolicy, route);
376	            }
377	        }
378	    }
379	
380	    private StartupStep beginStep(Service service, String description) {
381	        Class<?> type = service instanceof Processor ? Processor.class : Service.class;
382	        description = description + " " + service.getClass().getSimpleName();
383	        String id = null;
384	        if (service instanceof IdAware idAware) {
385	            id = idAware.getId();
386	        }
387	        return startupStepRecorder.beginStep(type, id, description);
388	    }
389	
390	    protected void initChildServices(List<Service> services) {
391	        for (Service service : services) {
392	            StartupStep step = null;
393	            // skip internal services / route pipeline (starting point for route)
394	            boolean shouldRecord
395	                    // NOTE: RoutePipeline belong to dependency not visible by this class at build time.
396	                    = !(service instanceof InternalProcessor || "RoutePipeline".equals(service.getClass().getSimpleName())); // NOSONAR
397	            if (shouldRecord) {
398	                step = beginStep(service, "Init");
399	            }
400	            ServiceHelper.initService(service);
401	            if (step != null) {
402	                startupStepRecorder.endStep(step);
403	            }
404	            // add and remember as child service
405	            addChildService(service);
406	        }
407	    }
408	
409	    protected void startChildServices(Route route, List<Service> services) {
410	        for (Service service : services) {
411	            StartupStep step = null;
412	            // skip internal services / route pipeline (starting point for route)
413	            boolean shouldRecord
414	                    // NOTE: RoutePipeline belong to dependency not visible by this class at build time.
415	                    = !(service instanceof InternalProcessor || "RoutePipeline".equals(service.getClass().getSimpleName())); // NOSONAR
416	            if (shouldRecord) {
417	                step = beginStep(service, "Start");
418	            }
419	            for (LifecycleStrategy strategy : camelContext.getLifecycleStrategies()) {
420	                strategy.onServiceAdd(camelContext, service, route);
421	            }
422	            ServiceHelper.startService(service);
423	            if (step != null) {
424	                startupStepRecorder.endStep(step);
425	            }
426	        }
427	    }
428	
429	    protected void stopChildServices(Route route, Set<Service> services, boolean shutdown) {
430	        for (Service service : services) {
431	            for (LifecycleStrategy strategy : camelContext.getLifecycleStrategies()) {
432	                strategy.onServiceRemove(camelContext, service, route, shutdown);
433	            }
434	            if (shutdown) {
435	                ServiceHelper.stopAndShutdownService(service);
436	            } else {
437	                ServiceHelper.stopService(service);
438	            }
439	            removeChildService(service);
440	        }
441	    }
442	
443	    /**
444	     * Gather all child services
445	     */
446	    private Set<Service> gatherChildServices() {
447	        List<Service> services = new ArrayList<>(route.getServices());
448	        // also get route scoped services
449	        doGetRouteServices(services);
450	        Set<Service> list = new LinkedHashSet<>();
451	        for (Service service : services) {
452	            list.addAll(ServiceHelper.getChildServices(service));
453	        }
454	        // also get route scoped error handler (which must be done last)
455	        doGetErrorHandler(list);
456	        return list;
457	    }
458	
459	    /**
460	     * Gather the route scoped error handler from the given route
461	     */
462	    private void doGetErrorHandler(Set<Service> services) {
463	        // only include error handlers if they are route scoped
464	        List<Service> extra = new ArrayList<>();
465	        for (Service service : services) {
466	            if (service instanceof Channel channel) {
467	                Processor eh = channel.getErrorHandler();
468	                if (eh instanceof Service s) {
469	                    extra.add(s);
470	                }
471	            }
472	        }
473	        if (!extra.isEmpty()) {
474	            services.addAll(extra);
475	        }
476	    }
477	
478	    /**
479	     * Gather all other kind of route services from the given route, except error handler
480	     */
481	    protected void doGetRouteServices(List<Service> services) {
482	        for (Processor proc : getRoute().getOnExceptions()) {
483	            if (proc instanceof Service service) {
484	                services.add(service);
485	            }
486	        }
487	        for (Processor proc : getRoute().getOnCompletions()) {
488	            if (proc instanceof Service service) {
489	                services.add(service);
490	            }
491	        }
492	    }
493	
494	    @Deprecated(since = "4.19.0")
495	    class MDCHelper implements AutoCloseable {
496	        final Map<String, String> originalContextMap;
497	
498	        MDCHelper(String routeId) {
499	            if (getCamelContext().isUseMDCLogging()) {
500	                originalContextMap = MDC.getCopyOfContextMap();
501	                MDC.put(MDC_CAMEL_CONTEXT_ID, getCamelContext().getName());
502	                MDC.put(MDC_ROUTE_ID, routeId);
503	            } else {
504	                originalContextMap = null;
505	            }
506	        }
507	
508	        @Override
509	        public void close() {
510	            if (getCamelContext().isUseMDCLogging()) {
511	                if (originalContextMap != null) {
512	                    MDC.setContextMap(originalContextMap);
513	                } else {
514	                    MDC.clear();
515	                }
516	            }
517	        }
518	
519	    }
520	
521	}
