155	    /**
156	     * Starts the routes services in a proper manner which ensures the routes will be started in correct order, check
157	     * for clash and that the routes will also be shutdown in correct order as well.
158	     * <p/>
159	     * This method <b>must</b> be used to start routes in a safe manner.
160	     *
161	     * @param  checkClash     whether to check for startup order clash
162	     * @param  startConsumer  whether the route consumer should be started. Can be used to warmup the route without
163	     *                        starting the consumer.
164	     * @param  resumeConsumer whether the route consumer should be resumed.
165	     * @param  addingRoutes   whether we are adding new routes
166	     * @param  routeServices  the routes
167	     * @throws Exception      is thrown if error starting the routes
168	     */
169	    private void safelyStartRouteServices(
170	            AbstractCamelContext camelContext,
171	            boolean checkClash, boolean startConsumer, boolean resumeConsumer, boolean addingRoutes,
172	            Collection<RouteService> routeServices)
173	            throws Exception {
174	        lock.lock();
175	        try {
176	            // list of inputs to start when all the routes have been prepared for
177	            // starting
178	            // we use a tree map so the routes will be ordered according to startup
179	            // order defined on the route
180	            Map<Integer, DefaultRouteStartupOrder> inputs = new TreeMap<>();
181	
182	            // figure out the order in which the routes should be started
183	            for (RouteService routeService : routeServices) {
184	                DefaultRouteStartupOrder order = doPrepareRouteToBeStarted(camelContext, routeService);
185	                // check for clash before we add it as input
186	                if (checkClash) {
187	                    doCheckStartupOrderClash(camelContext, order, inputs);
188	                }
189	                inputs.put(order.getStartupOrder(), order);
190	            }
191	
192	            // warm up routes before we start them
193	            doWarmUpRoutes(camelContext, inputs, startConsumer);
194	
195	            // sort the startup listeners so they are started in the right order
196	            camelContext.getStartupListeners().sort(OrderedComparator.get());
197	            // now call the startup listeners where the routes has been warmed up
198	            // (only the actual route consumer has not yet been started)
199	            for (StartupListener startup : camelContext.getStartupListeners()) {
200	                startup.onCamelContextStarted(camelContext.getCamelContextReference(), camelContext.isStarted());
201	            }
202	            // because the consumers may also register startup listeners we need to
203	            // reset
204	            // the already started listeners
205	            List<StartupListener> backup = new ArrayList<>(camelContext.getStartupListeners());
206	            camelContext.getStartupListeners().clear();
207	
208	            // now start the consumers
209	            if (startConsumer) {
210	                if (resumeConsumer) {
211	                    // and now resume the routes
212	                    doResumeRouteConsumers(camelContext, inputs, addingRoutes);
213	                } else {
214	                    // and now start the routes
215	                    // and check for clash with multiple consumers of the same
216	                    // endpoints which is not allowed
217	                    doStartRouteConsumers(camelContext, inputs, addingRoutes);
218	                }
219	            }
220	
221	            // sort the startup listeners so they are started in the right order
222	            camelContext.getStartupListeners().sort(OrderedComparator.get());
223	            // now the consumers that was just started may also add new
224	            // StartupListeners (such as timer)
225	            // so we need to ensure they get started as well
226	            for (StartupListener startup : camelContext.getStartupListeners()) {
227	                startup.onCamelContextStarted(camelContext.getCamelContextReference(), camelContext.isStarted());
228	            }
229	            // and add the previous started startup listeners to the list so we have
230	            // them all
231	            camelContext.getStartupListeners().addAll(0, backup);
232	
233	            // inputs no longer needed
234	            inputs.clear();
235	        } finally {
236	            lock.unlock();
