261	        Integer startupOrder = routeService.getRoute().getStartupOrder();
262	        if (startupOrder == null) {
263	            // auto assign a default startup order
264	            startupOrder = defaultRouteStartupOrder++;
265	        }
266	
267	        // create holder object that contains information about this route to be
268	        // started
269	        Route route = routeService.getRoute();
270	        return new DefaultRouteStartupOrder(startupOrder, route, routeService);
